553867e4-8b84-450b-b915-468da2b8ede3	[Context: diagnosis > hba1c | ada]\nWhether you're newly diagnosed, have had diabetes for a while, or you're helping a loved one, this is where you can get the tools, tips, and ideas to thrive with diabetes.\n\nWith your support, the American Diabetes Association® can continue our lifesaving work to make breakthroughs in research and provide people with the resources they need to fight diabetes.	{"url": "https://diabetes.org/about-diabetes/a1c", "title": "HbA1c", "topic": "hba1c", "source": "American Diabetes Association", "category": "diagnosis", "file_path": "diagnosis/hba1c/clean/ada/v5.md", "chunk_index": 2, "total_chunks": 3, "source_org_code": "ada", "parent_document_id": "19e45343-ae12-4729-845a-3c403fb95531"}	[0.018002737,-0.0044793976,-0.009173869,-0.05135253,-0.03897234,0.00028558754,0.008880231,-0.008654279,0.010799074,0.00082028157,0.0051848004,-0.012453331,-0.010190387,0.026438572,0.12412075,0.008823069,0.014197044,-0.014610617,0.011542077,0.00885834,-0.009304571,-0.016870461,0.024623876,-0.039822888,0.021225158,-0.008616628,0.032247808,0.01629454,0.024171999,0.035253394,0.0022682413,0.00013746835,0.026753828,0.013969731,0.014476231,0.014028764,-0.0003794763,-0.0097804805,0.017367154,-0.010234652,-0.0025674065,0.012600098,-0.007129197,-0.029306253,0.008022622,-0.0065428717,-0.006520105,-0.015268893,0.016387688,0.034247063,0.0011345359,-0.0015530944,-0.027640171,-0.17544423,0.020696575,-0.004033162,-0.029292947,0.030538367,-0.0034797143,-8.315827e-05,-0.016034087,0.028252244,-0.0073754257,-0.02810804,0.011377196,-0.033279717,0.009052576,-0.0027625205,-0.03366998,0.0015172574,0.022948718,-0.015677003,0.009583742,-0.020681113,-0.010494181,-0.0012857844,-0.011244463,-0.011451129,0.004946497,0.008273458,-0.012481777,-0.0143972505,-0.02866867,-0.011268016,-0.011975913,0.0017479517,-0.009961175,-0.014356587,0.002302243,0.019895662,0.0053445846,0.021935526,0.032776985,-0.023420516,-0.007900759,-0.030365396,-0.0043020356,-0.0